package io.earthplatform.compat.dh;

import com.seibel.distanthorizons.api.methods.events.abstractEvents.*;
import com.seibel.distanthorizons.api.methods.events.interfaces.IDhApiEvent;
import com.seibel.distanthorizons.api.methods.events.sharedParameterObjects.*;
import com.seibel.distanthorizons.api.interfaces.world.IDhApiLevelWrapper;
import java.lang.reflect.Proxy;
import java.nio.file.Path;
import java.util.*;
import java.util.concurrent.atomic.AtomicInteger;
import org.junit.jupiter.api.Test;
import static org.junit.jupiter.api.Assertions.*;

class InstalledDhContractsTest {
    static final ClassLoader LOADER=InstalledDhContractsTest.class.getClassLoader();
    static InstalledDhResolver.InstalledMod mod(){return new InstalledDhResolver.InstalledMod("3.3.3",Path.of("installed-dh.jar"),LOADER);}
    static InstalledDhResolver.Runtime runtime(){return new InstalledDhResolver.Runtime(mod(),InstalledDhContractsTest.class);}
    static InstalledDhResolver.Capabilities caps(boolean initialized,String engine){return new InstalledDhResolver.Capabilities(InstalledDhContractsTest.class,"3.3.3","7.2.0",initialized,"OPEN_GL",engine,"DEFAULT",true);}
    static final class Resource implements DhCarrierRenderGate.Resources {int draws,closes;boolean failClose;Runnable onDraw=()->{};public void draw(Object c){draws++;onDraw.run();}public void close(){closes++;if(failClose)throw new IllegalStateException("cleanup");}}
    static final class Registry implements InstalledDhEvents.Registry {
        final Map<Class<? extends IDhApiEvent>,IDhApiEvent> listeners=new HashMap<>();int calls,failBind=-1;boolean failUnbind;
        public boolean onlyListener(Class<? extends IDhApiEvent> type,IDhApiEvent exact){return listeners.get(type)==exact;}
        public void bind(Class<? extends IDhApiEvent> type,IDhApiEvent value){listeners.put(type,value);if(++calls==failBind)throw new IllegalStateException("bind after mutation");}
        public boolean unbind(Class<? extends IDhApiEvent> type,Class<? extends IDhApiEvent> value){if(failUnbind)throw new IllegalStateException("unbind");return listeners.remove(type)!=null;}
    }
    static DhApiCancelableEventParam<DhApiRenderParam> event(Object level){var params=new DhApiRenderParam();params.clientLevelWrapper=(IDhApiLevelWrapper)Proxy.newProxyInstance(LOADER,new Class[]{IDhApiLevelWrapper.class},(p,m,a)->{if(m.getName().equals("getWrappedMcObject"))return level;throw new UnsupportedOperationException(m.getName());});return new DhApiCancelableEventParam<>(params);}
    @Test void absentDoesNotProbeClassesOrArtifacts(){var n=new AtomicInteger();var r=new InstalledDhResolver(Optional::empty,l->{n.incrementAndGet();return caps(true,"OPEN_GL");},p->n.incrementAndGet());assertEquals(InstalledDhResolver.Status.ABSENT,r.resolve().status());assertEquals(0,n.get());}
    @Test void unsupportedVersionRejectsBeforeClassProbe(){var n=new AtomicInteger();var wrong=new InstalledDhResolver.InstalledMod("other",mod().path(),LOADER);var r=new InstalledDhResolver(()->Optional.of(wrong),l->{n.incrementAndGet();return caps(true,"OPEN_GL");},p->n.incrementAndGet());assertEquals(InstalledDhResolver.Status.UNSUPPORTED,r.resolve().status());assertEquals(0,n.get());}
    @Test void missingArtifactAndWrongApiHaveReadablePermanentRefusal(){var r=new InstalledDhResolver(()->Optional.of(mod()),l->caps(true,"OPEN_GL"),p->{throw new java.io.IOException("wrong hash");});assertTrue(r.resolve().explanation().contains("wrong hash"));assertSame(r.resolve(),r.resolve());var wrong=new InstalledDhResolver(()->Optional.of(mod()),l->new InstalledDhResolver.Capabilities(getClass(),"3.3.3","8.0.0",true,"OPEN_GL","OPEN_GL","DEFAULT",true),p->{});assertEquals(InstalledDhResolver.Status.UNSUPPORTED,wrong.resolve().status());}
    @Test void waitingInitAndModeChangesNeverInstallOrMutateDh(){var init=new boolean[]{false};var engine=new String[]{"OPEN_GL"};var hashes=new AtomicInteger();var r=new InstalledDhResolver(()->Optional.of(mod()),l->caps(init[0],engine[0]),p->hashes.incrementAndGet());assertEquals(InstalledDhResolver.Status.WAITING_FOR_INIT,r.resolve().status());init[0]=true;engine[0]="BLAZE_3D";assertEquals(InstalledDhResolver.Status.UNSUPPORTED,r.resolve().status());engine[0]="OPEN_GL";assertEquals(InstalledDhResolver.Status.READY,r.resolve().status());assertEquals(1,hashes.get());}
    @Test void installationOrClassIdentityCannotChangeAfterResolution(){var path=new InstalledDhResolver.InstalledMod[]{mod()};var r=new InstalledDhResolver(()->Optional.of(path[0]),l->caps(true,"OPEN_GL"),p->{});assertEquals(InstalledDhResolver.Status.READY,r.resolve().status());path[0]=new InstalledDhResolver.InstalledMod("3.3.3",Path.of("other.jar"),LOADER);assertEquals(InstalledDhResolver.Status.UNSUPPORTED,r.resolve().status());}
    @Test void exactCarrierOnlyAndOneSubmissionAcrossOpaqueDeferredDuplicates(){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();var lease=gate.acquire(runtime(),level,"world",1,1,owned);var cancels=new AtomicInteger();assertEquals(DhCarrierRenderGate.Result.PASS_THROUGH,gate.opaque(new Object(),1,1,false,true,cancels::incrementAndGet,null));assertEquals(0,cancels.get());assertEquals(DhCarrierRenderGate.Result.SUBMITTED,gate.opaque(level,1,1,false,true,cancels::incrementAndGet,null));gate.deferred(level,cancels::incrementAndGet);gate.opaque(level,1,1,false,true,cancels::incrementAndGet,null);assertEquals(1,owned.draws);assertEquals(3,cancels.get());assertTrue(gate.isCurrent(lease));gate.close();assertEquals(1,owned.closes);}
    @Test void priorCancellationResourceModeOrFrameRegressionFencesWithoutFallback(){for(int kind=0;kind<4;kind++){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();var lease=gate.acquire(runtime(),level,"world",1,1,owned);if(kind==3)gate.opaque(level,10,1,false,true,()->{},null);gate.opaque(level,kind==3?9:1,kind==1?2:1,kind==0,kind!=2,()->{},null);assertFalse(gate.isCurrent(lease));assertEquals(kind==3?1:0,owned.draws);gate.close();}}
    @Test void reloadAndUnloadKeepSuppressionUntilCleanupButNeverTouchOtherWorlds(){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();var lease=gate.acquire(runtime(),level,"world",1,1,owned);gate.levelUnloaded(new Object());assertTrue(gate.isCurrent(lease));gate.levelUnloaded(level);assertFalse(gate.isCurrent(lease));var n=new AtomicInteger();gate.opaque(level,1,1,false,true,n::incrementAndGet,null);assertEquals(1,n.get());assertEquals(0,owned.draws);gate.close();assertEquals(DhCarrierRenderGate.Result.PASS_THROUGH,gate.deferred(level,n::incrementAndGet));}
    @Test void failedCleanupRetainsCarrierAndRefusesAnotherSessionUntilRetry(){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();gate.acquire(runtime(),level,"world",1,1,owned);owned.failClose=true;assertThrows(IllegalStateException.class,gate::close);assertTrue(gate.counters().cleanupPending());assertThrows(IllegalStateException.class,()->gate.acquire(runtime(),new Object(),"next",2,1,new Resource()));assertEquals(DhCarrierRenderGate.Result.CANCELLED,gate.deferred(level,()->{}));owned.failClose=false;gate.close();assertFalse(gate.counters().ownsCarrier());}
    @Test void drawFailureAndReentrantInvalidationCannotLeaveCurrentAuthority(){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();var lease=gate.acquire(runtime(),level,"world",1,1,owned);owned.onDraw=()->{gate.invalidate("reload");};assertEquals(DhCarrierRenderGate.Result.CANCELLED,gate.opaque(level,1,1,false,true,()->{},null));assertFalse(gate.isCurrent(lease));gate.close();}
    @Test void actualApiEventListenersCancelBeforeCallbackAndContainOwnFailures(){var gate=new DhCarrierRenderGate();var level=new Object();var owned=new Resource();gate.acquire(runtime(),level,"world",1,1,owned);var registry=new Registry();var errors=new AtomicInteger();var events=new InstalledDhEvents(gate,()->new InstalledDhEvents.Frame(1,1,true),t->errors.incrementAndGet(),registry);events.start();try{var e=event(level);owned.onDraw=()->{assertTrue(e.isEventCanceled());throw new IllegalStateException("our draw");};assertDoesNotThrow(()->((DhApiBeforeRenderEvent)registry.listeners.get(DhApiBeforeRenderEvent.class)).beforeRender(e));assertEquals(1,errors.get());assertTrue(e.isEventCanceled());assertTrue(gate.counters().fenced());var ordinary=event(new Object());((DhApiBeforeRenderEvent)registry.listeners.get(DhApiBeforeRenderEvent.class)).beforeRender(ordinary);assertFalse(ordinary.isEventCanceled());var d=event(level);((DhApiBeforeDeferredRenderEvent)registry.listeners.get(DhApiBeforeDeferredRenderEvent.class)).beforeRender(d);assertTrue(d.isEventCanceled());}finally{events.close();}assertEquals(0,events.retainedBindings());}
    @Test void partialRegistrationAndUnregistrationRetainRetryableOwnership(){var gate=new DhCarrierRenderGate();var registry=new Registry();registry.failBind=2;registry.failUnbind=true;var events=new InstalledDhEvents(gate,()->new InstalledDhEvents.Frame(1,1,true),t->{},registry);assertThrows(IllegalStateException.class,events::start);assertEquals(2,events.retainedBindings());assertThrows(IllegalStateException.class,()->new InstalledDhEvents(new DhCarrierRenderGate(),()->new InstalledDhEvents.Frame(1,1,true),t->{},new Registry()).start());registry.failUnbind=false;events.close();assertTrue(registry.listeners.isEmpty());}
    @Test void eventsRemainBoundWhenOwnedGpuCleanupFails(){var gate=new DhCarrierRenderGate();var r=new Resource();gate.acquire(runtime(),new Object(),"world",1,1,r);var registry=new Registry();var events=new InstalledDhEvents(gate,()->new InstalledDhEvents.Frame(1,1,true),t->{},registry);events.start();r.failClose=true;assertThrows(IllegalStateException.class,events::close);assertEquals(4,events.retainedBindings());r.failClose=false;events.close();assertTrue(registry.listeners.isEmpty());}
    @Test void eventSourceContainsNoGlobalDhClearOverrideOrSettingsMutation(){for(var m:InstalledDhEvents.class.getDeclaredMethods())assertNotEquals("clear",m.getName());assertFalse(AutoCloseable.class.isAssignableFrom(InstalledDhResolver.Runtime.class));}
}
